// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    function setUp() public { c = new PuttyV2("", 1, address(this)); }

    function testFuzz_property(uint256 seed) public {
        uint256 f = bound(seed, 1, 29);
        c.setFee(f);

        // Token contract used as the `asset` key for the fee ledger.
        address asset = address(new ERC20("T", "T", 18));
        address recipient = address(0xBEEF);

        uint256 before = c.unclaimedFees(asset);

        uint256 balBefore = ERC20(asset).balanceOf(recipient);

        c.withdrawFees(asset, recipient);

        uint256 afterFees = c.unclaimedFees(asset);

        // Reference: fees paid out, ledger key cleared to zero (mint zero-writes allowed).
        // Mutant: ledger key set to `fee`, so for any asset key with no genuine fee it becomes nonzero.
        assertTrue(afterFees == 0 || afterFees == before - (before - afterFees));

        // Stronger direct form: the amount transferred to the recipient equals
        // the amount removed from `unclaimedFees` at `asset`.
        uint256 balAfter = ERC20(asset).balanceOf(recipient);
        assertTrue((balAfter - balBefore) + afterFees == before);
    }
}

contract ERC20 {
    string public name;
    string public symbol;
    uint8 public decimals;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 amount);
    event Approval(address indexed owner, address indexed spender, uint256 amount);

    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) allowance[from][msg.sender] = allowed - amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }
}
